    "Nearest Hospital": "Bhailal Amin General Hospital",
    "Hospital Distance Quality": "Approximate / locality-based",
    "Nearest Fire Station": "Akota-area fire station (verify current station)",
    "Fire Distance Quality": "Approximate / locality-based",
    "Vadodara Junction Distance (km)": 4,
